<?php
require __DIR__.'/config.php'; require __DIR__.'/layout.php'; require_login();
$table='LEE_contacts'; $pk='contact_id'; $fields=['name', 'email', 'message', 'submitted_at', 'is_read']; $labels=['姓名', 'Email', '留言', '時間', '已讀'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $data=array_map(fn($f)=>$_POST[$f]??null,$fields); if(($_POST['id']??'')!==''){ $data[]=$_POST['id']; db()->prepare('UPDATE '.$table.' SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).' WHERE '.$pk.'=?')->execute($data); flash('資料已更新'); } else { db()->prepare('INSERT INTO '.$table.' ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($data); flash('資料已新增'); } redirect_to(basename(__FILE__)); }
if(isset($_GET['delete'])){ db()->prepare('DELETE FROM '.$table.' WHERE '.$pk.'=?')->execute([$_GET['delete']]); flash('資料已刪除'); redirect_to(basename(__FILE__)); }
$edit=null; if(isset($_GET['edit'])){ $st=db()->prepare('SELECT * FROM '.$table.' WHERE '.$pk.'=?'); $st->execute([$_GET['edit']]); $edit=$st->fetch(); }
$rows=db()->query('SELECT * FROM '.$table.' ORDER BY '.$pk.' DESC LIMIT 200')->fetchAll(); admin_header('聯絡表單');
?><section class="panel"><form method="post"><input type="hidden" name="id" value="<?=h($edit[$pk]??'')?>"><div class="grid"><?php foreach($fields as $i=>$f): ?><label><?=h($labels[$i])?><input class="form-control" name="<?=h($f)?>" value="<?=h($edit[$f]??'')?>"></label><?php endforeach; ?></div><button class="btn btn-primary mt-3">儲存</button></form></section><section class="panel"><table class="table"><tr><th>ID</th><?php foreach($labels as $l) echo '<th>'.h($l).'</th>'; ?><th>操作</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r[$pk])?></td><?php foreach($fields as $f): ?><td><?=h($r[$f]??'')?></td><?php endforeach; ?><td><a href="?edit=<?=h($r[$pk])?>">編輯</a> <a href="?delete=<?=h($r[$pk])?>" onclick="return confirm('確定刪除?')">刪除</a></td></tr><?php endforeach; ?></table></section><?php admin_footer(); ?>
